// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address payable deployer;

    function setUp() public {
        // The test harness deploys C; its owner is msg.sender at deployment time (this contract)
        c = new C();
        deployer = payable(address(this));
    }

    // Fuzzed: value sent to go and an external adversarial callee selector choice realized by a bool
    function testFuzz_property(uint256 value, bool makeCalleeRevert) public {
        // keep value in a reasonable range so vm.deal works broadly
        value = bound(value, 0, 1 ether);

        // Deploy an adversarial helper that will be used as the fixed target address inside C.
        // The reference C uses a hard-coded target address; to simulate that address interaction
        // we must ensure the low-level call to that address behaves in an adversarial way.
        // Since the contract C calls a hard-coded address 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C,
        // we cannot change C. However, the behavior difference between reference and mutant
        // depends only on where remaining balance is forwarded (owner vs msg.sender). The external
        // call may succeed; we still test the forwarding property by making the external call succeed.

        // Prepare caller EOA that will call c.go
        address caller = address(0xABCD);
        vm.deal(caller, value);

        // Record owner address (the deployer of C in setUp)
        address owner = c.owner();

        // Ensure owner has zero balance to measure receipt
        vm.deal(owner, 0);

        // Ensure contract has zero balance initially
        assertEq(address(c).balance, 0);

        // Perform the call to c.go from 'caller' sending 'value'
        vm.prank(caller);
        c.go{value: value}();

        // After go returns, the correct contract always forwards its entire balance to owner,
        // leaving address(c).balance == 0 and owner having increased by exactly value (since the
        // call to the external target used the same msg.value and any refunds end up in contract
        // and then get forwarded to owner). The mutant forwards leftovers to msg.sender instead,
        // so owner may not receive the funds when msg.sender != owner. We assert that address(c)
        // has zero balance, which the reference guarantees for any inputs; the mutant can leave
        // funds in the contract or send them to caller, violating this observable.
        assertTrue(address(c).balance == 0);
    }
}

