pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // adversarial callee that accepts Ether and does nothing (so call succeeds)
    // We need such a helper so the fuzzer can choose its address as the target if needed,
    // but here target is hardcoded in C; still deploy a payable helper to receive funds when
    // we route the call through msg.sender behavior (not necessary here), however the main
    // requirement is to fuzz the amount and caller.

    function setUp() public { c = new C(); }

    // Fuzz the amount and the actor sending the funds. The general property:
    // After a successful call to go{value: amount} by any actor, the contract balance must be zero
    // because the reference forwards remaining balance to owner. The mutant removing that transfer
    // will leave a non-zero balance for some amount/actor combinations.
    function testFuzz_property(uint256 amount, address payer) public {
        // keep payer realistic: non-zero address
        vm.assume(payer != address(0));
        // limit amount to a reasonable upper bound to avoid blowing EVM limits in fuzz
        amount = bound(amount, 0, 1 ether);

        // fund the payer
        vm.deal(payer, amount);

        // perform the call from payer sending amount wei
        vm.prank(payer);
        // wrap call in try/catch to ensure we only assert on successful completion
        bool ok;
        try c.go{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for the correct contract, whenever the external call completes successfully,
        // the contract forwards remaining balance to owner, leaving address(c).balance == 0.
        // We therefore assert that if the call succeeded, the contract's balance is zero.
        assertTrue(!ok || address(c).balance == 0);
    }
}

