pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the amount sent and the behavior of the callee via a boolean flag
    // amount: how much wei the fuzzer sends to c.go{value: amount}()
    // eatAll: when true, the helper will consume any value sent to it (do nothing special),
    //         when false, the helper will revert on receiving funds — we need a callee that accepts and doesn't revert
    // We only need one helper type below; we fuzz the amount and which helper we use by deploying one and passing its address.
    function testFuzz_property(uint256 amount, bool attackerConsumes) public {
        // keep amount reasonable but wide
        amount = bound(amount, 0, 1 ether);

        // Deploy helper that will accept the forwarded call; if attackerConsumes==true it will keep the funds (just accept),
        // otherwise it will accept as well — both accept; the key is we use a helper address (non-EOA) so the low-level call can
        // execute code and potentially change behavior. We don't want the callee to revert because original contract expects success.
        Helper h = new Helper(attackerConsumes);

        // Fund the caller so it can send ETH
        address caller = address(0xBEEF);
        vm.deal(caller, amount);
        vm.prank(caller);
        // Call go, passing the helper's address by relying on the fixed target inside C: since C uses a hardcoded address,
        // we cannot change the target. To route C's external call through an adversarial party, we instead deploy a
        // ProxyC that forwards to the real C? The problem statement mandates using given C via new C() in setUp(),
        // and we must call its go(). The only effective way is to make the hardcoded target address equal to our helper.
        // But we cannot change C; however in the provided description the difference manifests as leftover balance in C when
        // the external call succeeded. We can still observe address(c).balance after calling go(). If the external callee is
        // an address with code, the call may forward gas and effect behavior. We therefore ensure the helper exists at the
        // target address by deploying it at that address using create2. The target in C is 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C.

        address target = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        // deploy helper at exact target using create2
        bytes memory initCode = type(Helper).creationCode;
        initCode = abi.encodePacked(initCode, abi.encode(attackerConsumes));
        // compute salt deterministically from helper address we already have
        bytes32 salt = keccak256(abi.encodePacked(uint256(uint160(address(h)))));
        address deployed;
        assembly {
            deployed := create2(0, add(initCode, 0x20), mload(initCode), salt)
        }
        // if deployment failed due to existing code at target, ensure it's the desired address
        // (forge local tests will allow create2 to deploy; if code already exists, skip)

        // Now call c.go with the fuzzed amount
        vm.prank(caller);
        c.go{value: amount}();

        // The general property: after a successful go(), the correct contract forwards its remaining balance so address(c).balance == 0.
        // The mutant that removed the transfer can leave a positive balance for some input; thus we assert that address(c).balance == 0.
        assertTrue(address(c).balance == 0);
    }
}

contract Helper {
    bool public consume;
    constructor(bool _consume) payable {
        consume = _consume;
    }
    // Accept calls and do nothing special. Existence of code at the target makes the low-level call actually execute this fallback.
    fallback() external payable {
        // if consume==true, do nothing (keep funds in helper)
        // if consume==false, also do nothing; both accept. The distinguisher is presence of code at target so C's call executes.
    }
}

