pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to send and a boolean deciding whether the adversary will consume the forwarded value
    function testFuzz_property(uint256 amount, bool consumeAll) public {
        // keep amount in a reasonable range but wide so bug-triggering values remain admissible
        amount = bound(amount, 0, 1 ether);

        // deploy adversarial callee that can re-enter C during its fallback/receive
        ReentrantCallee attacker = new ReentrantCallee(address(c));

        // fund the attacker so it can forward funds to target if needed
        vm.deal(address(attacker), 1 ether);

        // set behaviour: if consumeAll==true, callee will accept and not re-enter (simulate normal accept);
        // if false, callee will re-enter into c.go() while the original call frame still holds funds in c,
        // causing a path where retention of balance by mutant becomes observable.
        attacker.setConsumeAll(consumeAll);

        // choose an externally owned address as the msg.sender for c.go; fund it
        address caller = address(0xBEEF);
        vm.deal(caller, amount + 1 wei);
        vm.prank(caller);

        // perform the payable call to go, routed through the adversarial callee's address
        // The contract C has its target address hardcoded; attacker will proxy the call by first calling C.go
        // so that inside C's external call it calls attacker (we simulate by making attacker call C.go and attacker
        // supplying itself as the low-level callee via being the target of some side-effect — attacker will call C.go directly)
        // To trigger the interaction, attacker will call c.go{value: amount}()

        // attacker has funds; let it invoke c.go with the fuzzed amount
        attacker.invokeGo{value: amount}();

        // After call completes, the reference C always forwards remaining balance to owner and thus
        // address(c).balance == 0 for all admissible inputs. The mutant that removed the transfer may leave a
        // positive balance in C for some inputs (the reentrant scenario). Assert the universal property
        // that address(c).balance == 0. This holds for the reference but will fail on the mutant for some inputs.
        assertTrue(address(c).balance == 0);
    }
}

// Minimal adversarial helper that can optionally re-enter C during its receive/fallback
contract ReentrantCallee {
    address cAddr;
    bool consumeAll;
    constructor(address _cAddr) payable {
        cAddr = _cAddr;
        consumeAll = true;
    }
    function setConsumeAll(bool v) public {
        consumeAll = v;
    }
    // allow receiving ETH; optionally re-enter C.go during receive
    receive() external payable {
        if (!consumeAll) {
            // re-enter C.go with zero value to trigger potential inconsistent state in mutant
            // use a low gas call to avoid affecting revert semantics
            (bool ok, ) = cAddr.call(abi.encodeWithSignature("go()"));
            ok; // ignore result
        }
    }
    // helper to invoke c.go paying some value from this contract
    function invokeGo() public payable {
        // forward entire balance passed in msg.value to C
        C(cAddr).go{value: msg.value}();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: amount of ETH sent to c.go and an address to act as the caller
    function testFuzz_property(uint256 amt, address caller) public {
        // keep amount within reasonable bounds and caller non-zero
        vm.assume(caller != address(0));
        uint256 value = bound(amt, 1 wei, 1 ether);

        // Deploy an adversarial callee that will accept the low-level call but then revert
        // This forces C to temporarily retain balance after the call returns (the call failed)
        Reverter r = new Reverter();

        // fund the caller so they can send value
        vm.deal(caller, value);
        vm.startPrank(caller);
        // The contract C uses a hard-coded target address in source, so we cannot change it there.
        // To force C to interact with our Reverter, we instead deploy a proxy that forwards any call
        // to the hard-coded target address by making the Reverter appear at that address using
        // an address alias is not possible here — however, we can still exercise the difference by
        // making the low-level call to the hard-coded address revert via selfdestruct trick: create a contract
        // at that exact address is infeasible. Instead, we trigger the observed difference by making the low-level
        // target call fail via calling from an address that will cause the target call to revert: the Reverter
        // will be invoked by the target call if the target address equals the Reverter address. To achieve this
        // despite the hard-coded address in C, we simulate the same effect by directly calling go on c with value
        // while the Callee (the network) causes the internal call to revert — Achieve this by making the target address
        // contain code that reverts. Since C's target is fixed in the source, the only reliable adversarial behavior
        // we can produce from here that distinguishes the removed transfer is when the external low-level call returns
        // with success=false (i.e. reverts) so C retains funds; our Reverter will be used by sending the transaction value
        // from the caller to C.go and then performing a low-level call to the Reverter to simulate the failing external call.
        // To actually cause C's internal call to fail we cannot change C's hardcoded target; however, the general property we assert
        // is that after a successful invocation of go (i.e., it does not revert), the correct contract leaves its balance == 0.
        // We therefore perform the call and assert that address(c).balance == 0 for the reference implementation.

        // Call c.go with value from caller
        try c.go{value: value}() {
            // successful invocation
        } catch {
            // if it reverts, just stop the prank and skip (we only assert on successful calls)
            vm.stopPrank();
            return;
        }
        vm.stopPrank();

        // EXACTLY ONE assertion: reference C should always forward remaining balance to owner so contract balance is zero
        assertTrue(address(c).balance == 0);
    }
}

// Minimal adversarial helper: a contract whose fallback reverts
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
}
